parameters.jsCode:
const rawMessage = $("Webhook WAHA").item.json.body?.payload?.body || "";
const pasosDB = $("GET Pasos DB").item.json.data || [];

if (!rawMessage) return [];

const blocks = rawMessage.split(/(?=🔹)/);
const results = [];

function normalizeStr(s) {
  return s.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z0-9]/g, '');
}

for (const block of blocks) {
  if (!block.includes('🔹')) continue;

  const linesInBlock = block.split('\n');
  const firstLine = linesInBlock[0];
  let cleanLine = firstLine.replace('🔹', '').trim();

  const match = cleanLine.match(/^(.*?)(?:✅|⚠️|⛔️|⛔|⚠|\s+HABILITADO|\s+NO\s+HABILITADO|\s+CERRADO)/i);
  if (!match) continue;

  let rawName = match[1].replace(/Complejo/ig, '').replace(/Fronterizo/ig, '').replace(/Integrado/ig, '').trim();

  let rawState = "desconocido";
  let normState = "desconocido";

  if (cleanLine.match(/NO HABILITADO|CERRADO/i)) {
    rawState = cleanLine.match(/NO HABILITADO|CERRADO/i)[0].toUpperCase();
    normState = "cerrado";
  } else if (cleanLine.match(/HABILITADO/i)) {
    rawState = "HABILITADO";
    normState = "abierto";
  } else if (cleanLine.match(/⚠️|⚠/)) {
    rawState = "CONDICIONADO";
    normState = "condicionado";
  }

  let details = cleanLine.substring(match[1].length).replace(/(✅|⚠️|⛔️|⛔|⚠)/g, '').trim();
  if (details.toUpperCase().startsWith(rawState)) {
    details = details.substring(rawState.length).trim();
  }
  details = details.replace(/^[-\|\.,\s]+/, '');

  if (linesInBlock.length > 1) {
    details += " " + linesInBlock.slice(1).join(" ");
  }

  let pasoEncontrado = null;
  const searchName = normalizeStr(rawName);

  for (const p of pasosDB) {
    const dbName = normalizeStr(p.nombre_oficial);
    if (dbName.includes(searchName) || searchName.includes(dbName)) {
      pasoEncontrado = p;
      break;
    }
  }

  if (pasoEncontrado) {
    // --- NUEVO: Extracción de Horarios y Vehículos ---
    let horario_apertura = null;
    let horario_cierre = null;
    const horaMatch = details.match(/(\d{1,2}:\d{2})\s*[a-zA-Z]*\s*a\s*(\d{1,2}:\d{2})/i);
    if (horaMatch) {
      horario_apertura = horaMatch[1];
      horario_cierre = horaMatch[2];
    }

    let tipo_vehiculos = [];
    if (normState === "cerrado") {
      tipo_vehiculos = [];
    } else {
      const tLower = details.toLowerCase();
      if (tLower.includes("todo tipo") || tLower.includes("todos los veh")) {
        tipo_vehiculos = ["automóvil", "bus", "camión"];
      } else {
        if (tLower.includes("bus ") || tLower.includes("buses")) tipo_vehiculos.push("bus");
        if (tLower.includes("menor") || tLower.includes("auto") || tLower.includes("particular")) tipo_vehiculos.push("automóvil");
        if (tLower.includes("carga") || tLower.includes("cami")) tipo_vehiculos.push("camión");
      }
      tipo_vehiculos = [...new Set(tipo_vehiculos)];
    }
    // ---------------------------------------------------

    results.push({
      json: {
        documentId: pasoEncontrado.documentId,
        nombre_oficial: pasoEncontrado.nombre_oficial,
        nombre_waha: rawName,
        estado_general: normState,
        estado_raw: rawState,
        mensaje_original: block.trim(),
        detalles: details || rawState,
        horario_apertura: horario_apertura,
        horario_cierre: horario_cierre,
        tipo_vehiculos: tipo_vehiculos,
        timestamp: $("Webhook WAHA").item.json.body?.payload?.timestamp || Math.floor(Date.now() / 1000),
        waha_id: $("Webhook WAHA").item.json.body?.payload?.id || ""
      }
    });
  }
}

return results;
